import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CreateUserWalletResponse, PinNumRequestDTO } from '~/entities/pin/api/dtos/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const createUserWallet = (pinModel: PinNumRequestDTO) => {
  return resultify<CreateUserWalletResponse>(axios.post(`${API_URLS.createUserWallet}`, pinModel));
};

export const useCreateUserWalletMutation = (
  options?: MutationOptions<PinNumRequestDTO, CBDCAxiosError, CreateUserWalletResponse>,
) => {
  const mutation = useMutation<CreateUserWalletResponse, CBDCAxiosError, PinNumRequestDTO>({
    mutationFn: (pinModel: PinNumRequestDTO) => createUserWallet(pinModel),

    ...options,
  });

  return {
    ...mutation,
  };
};
