import { useStore } from '~/app/store/store';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { PIN_CONSTANTS } from './constants';

export const useCreatePin = () => {
  const { openAlertDialog } = useAlertDialog();

  // 간편 비밀번호 설정
  const handleStepOne = () => {
    const isSequentialOrSameNumber = useStore.getState().pinSlice.isSequentialOrSameNumber;
    const fnChkUserData = useStore.getState().pinSlice.fnChkUserData;
    const setPropsOnSecondStep = useStore.getState().pinSlice.setPropsOnSecondStep;
    const pin = useStore.getState().pinSlice.pin;
    const handleErrorMessage = useStore.getState().pinSlice.handleErrorMessage;
    const resetPropsOnError = useStore.getState().pinSlice.resetPropsOnError;

    const isPinInvalid = isSequentialOrSameNumber(pin) || fnChkUserData(pin);

    const resetProps = () =>
      resetPropsOnError({
        title: i18n.t('pin:titleSetPin'),
        message: i18n.t('pin:messageSetPin'),
      });

    const handleInvalidPin = () => {
      handleErrorMessage(i18n.t('pin:messageSetPin'));
      openAlertDialog({
        message: i18n.t('pin:errorResetPin'),
        onConfirmClick: resetProps,
      });
    };

    const handleValidPin = () => {
      setPropsOnSecondStep({
        title: i18n.t('pin:titleSetPinConfirm'),
        message: i18n.t('pin:messageSetPinConfirm'),
      });
    };

    return isPinInvalid ? handleInvalidPin() : handleValidPin();
  };

  const handleStepTwo = () => {
    const currentPin = useStore.getState().pinSlice.pin;
    const prevPin = useStore.getState().pinSlice.prevPin;
    const incorrectPinCount = useStore.getState().pinSlice.incorrectPinCount;
    const setIncorrectPinCount = useStore.getState().pinSlice.setIncorrectPinCount;
    const setPropsOnCompleteStep = useStore.getState().pinSlice.setPropsOnCompleteStep;
    const handleErrorMessage = useStore.getState().pinSlice.handleErrorMessage;
    const resetPropsOnError = useStore.getState().pinSlice.resetPropsOnError;

    const isPinMatching = prevPin === currentPin;

    const handleMatchingPin = () => {
      setPropsOnCompleteStep({
        title: i18n.t('pin:titleSetPin'),
        message: i18n.t('pin:messageSetPin'),
      });
    };

    const handleNonMatchingPin = () => {
      const newIncorrectCount = incorrectPinCount + 1;
      setIncorrectPinCount(newIncorrectCount);

      const msg = i18n.t('pin:errorDifferentInputPin', { cnt: incorrectPinCount + 1 });
      handleErrorMessage(msg);

      const isMaxIncorrectReached = newIncorrectCount > PIN_CONSTANTS.MAX_INCORRECT_COUNT;

      if (isMaxIncorrectReached) {
        openAlertDialog({
          message: i18n.t('pin:errorMaxIncorrectPin'),
          onConfirmClick: () => {
            resetPropsOnError({
              title: i18n.t('pin:titleSetPin'),
              message: i18n.t('pin:messageSetPin'),
            });
          },
        });
      }
    };

    return isPinMatching ? handleMatchingPin() : handleNonMatchingPin();
  };

  const handleCreatePin = () => {
    const step = useStore.getState().pinSlice.step;
    return step === PIN_CONSTANTS.STEP.FIRST ? handleStepOne() : handleStepTwo();
  };

  return { handleCreatePin };
};
