import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { useStore } from '~/app/store/store';
import { CheckPinNumResponseDTO, PinNumRequestDTO } from '~/entities/pin/api/dtos/types';
import { getLatestTranskeyModel } from '~/entities/pin/lib/get-latest-transkey-model';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { resultify } from '~/shared/lib/utils/resultify';

const getCheckPinNum = (pinModel: PinNumRequestDTO) => {
  const requestPayload: PinNumRequestDTO = {
    ...pinModel,
    transkeyModel: getLatestTranskeyModel(pinModel.transkeyModel),
  };

  return resultify(axios.post<CheckPinNumResponseDTO>(`${API_URLS.checkPinNum}`, requestPayload));
};

export const useGetCheckPinNumMutation = (
  options?: MutationOptions<PinNumRequestDTO, CBDCAxiosError, CheckPinNumResponseDTO>,
) => {
  const { openAlertDialog } = useAlertDialog();
  const setIncorrectPinCount = useStore.getState().pinSlice.setIncorrectPinCount;
  const mutation = useMutation<CheckPinNumResponseDTO, CBDCAxiosError, PinNumRequestDTO>({
    ...options,
    mutationFn: (pinModel: PinNumRequestDTO) => getCheckPinNum(pinModel),
    onSuccess: (data) => {
      if (data.accessToken?.length > 0) {
        setIncorrectPinCount(0);
      } else {
        const incorrectPinCount = useStore.getState().pinSlice.incorrectPinCount;
        const failCnt = incorrectPinCount > 5 ? 5 : incorrectPinCount + 1;
        setIncorrectPinCount(failCnt);
      }
    },
    onError: (error) => {
      if (error?.response?.data?.message) {
        openAlertDialog({ message: error.response.data.message });
      }
    },
  });

  return {
    ...mutation,
  };
};
