import { useRef } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { useStore } from '~/app/store/store';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { useGetConfirmUserMutation } from '~/entities/intro/api/use-get-confirm-user-mutation';
import { useCreateUserWalletMutation } from '~/entities/pin/api/use-create-user-wallet-mutation';
import { useVerifyPinMutation } from '~/entities/pin/api/use-verify-pin-mutation';
import { getLatestTranskeyModel } from '~/entities/pin/lib/get-latest-transkey-model';
import { getUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { CBDCAxiosError } from '~/shared/@types/error';
import { LoginType, PinFailType, SuperAppCommandInbound } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';
import { PIN_CONSTANTS } from './constants';

export const useVerifyPin = () => {
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const { mutateAsync: getConfirmUser } = useGetConfirmUserMutation();
  const { mutateAsync: verifyPin } = useVerifyPinMutation({ throwOnError: false });
  const { mutateAsync: createUserWallet } = useCreateUserWalletMutation({ throwOnError: false });
  const { openAlertDialog } = useAlertDialog();
  const { navigate } = useNavigate();
  const isFail = useRef(false);
  const failCnt = useRef<number>();

  const [
    pin,
    handleShuffle,
    triggerCompleteInput,
    isPinEmpty,
    isPinLengthInvalid,
    shouldShowPinError,
    calculateFailCount,
    handleErrorMessage,
    isFailCountInitRequired,
    setIsError,
  ] = useStore(
    useShallow((s) => [
      s.pinSlice.pin,
      s.pinSlice.handleShuffle,
      s.pinSlice.triggerCompleteInput,
      s.pinSlice.isPinEmpty,
      s.pinSlice.isPinLengthInvalid,
      s.pinSlice.shouldShowPinError,
      s.pinSlice.calculateFailCount,
      s.pinSlice.handleErrorMessage,
      s.pinSlice.isFailCountInitRequired,
      s.pinSlice.setIsError,
    ]),
  );

  // 비밀번호 인증
  const handleVerifyPin = async () => {
    const userRes = getUserRes();

    if (isPinEmpty(pin)) return;
    if (isPinLengthInvalid(pin)) {
      try {
        const reqData = { cstmrNo: userRes?.tbCstmrMastr?.cstmrNo };

        if (isFailCountInitRequired(failCnt.current)) {
          const response = await getConfirmUser(reqData);
          failCnt.current = calculateFailCount(response.failrCo);
        }
        if (failCnt?.current && failCnt.current > 0) {
          handleErrorMessage(i18n.t('pin:errorDifferentInputPin', { cnt: failCnt.current! }));
        }
        if (isPinEmpty(pin) && shouldShowPinError(failCnt.current!, isFail.current)) {
          const currentFailCount = failCnt.current!;
          handleErrorMessage(i18n.t('pin:errorDifferentInputPin', { cnt: currentFailCount }));

          if (currentFailCount > PIN_CONSTANTS.MAX_INCORRECT_COUNT) {
            openAlertDialog({
              message: i18n.t('pin:errorMaxPin'),
              onConfirmClick: () => {
                setTimeout(() => {
                  navigate(PATHS.pwFail, { state: { ...state, type: PinFailType.로그인실패 }, replace: true });
                }, PIN_CONSTANTS.NAVIGATION_DELAY);
              },
            });
          }
        }
      } catch (e: any) {
        const data = e?.response?.data || {};
        if (data?.message) {
          openAlertDialog({ message: data.message });
        }
      }

      setIsError(false);
      return;
    }

    // 간편비밀번호 로그인
    const nextSid = state?.sid || null;
    const newUserParam = {
      tbCstmrMastr: {
        cstmrNo: userRes?.tbCstmrMastr?.cstmrNo,
        loginType: LoginType.간편비밀번호,
        pin: pin,
      },
      sid: nextSid,
      transkeyModel: getLatestTranskeyModel(userRes?.transkeyModel),
    };

    // 핀번호 로그인
    let isLogin = false;
    try {
      useStore.getState().authSlice.setJwt(null);
      await verifyPin(newUserParam);
      isLogin = true;
    } catch (e) {
      isLogin = false;
    }

    if (isLogin && state?.command === SuperAppCommandInbound.지갑추가_요청) {
      await createUserWallet(userRes);
      // setUserRes((prev) => ({
      //   ...prev,
      //   aliasNm: data.aliasNm,
      // }));
    }

    if (!isLogin) {
      isFail.current = true;
      try {
        const reqData = { cstmrNo: userRes?.tbCstmrMastr?.cstmrNo };
        const response = await getConfirmUser(reqData);
        failCnt.current = calculateFailCount(response.failrCo);

        const currentFailCount = failCnt.current;
        handleErrorMessage(i18n.t('pin:errorDifferentInputPin', { cnt: currentFailCount }));

        if (currentFailCount > PIN_CONSTANTS.MAX_INCORRECT_COUNT) {
          openAlertDialog({
            message: i18n.t('pin:errorMaxPin'),
            onConfirmClick: () => {
              setTimeout(() => {
                navigate(PATHS.pwFail, { state: { ...state, type: PinFailType.로그인실패 }, replace: true });
              }, PIN_CONSTANTS.NAVIGATION_DELAY);
            },
          });
        }
      } catch (e: unknown) {
        const data = (e as CBDCAxiosError)?.response?.data || {};
        if (data?.message) {
          openAlertDialog({
            message: data.message,
          });
        }
      }

      return;
    }

    triggerCompleteInput();
    handleShuffle();
  };

  return { handleVerifyPin };
};
